<?php
require __DIR__.'/../database/runtime.php';
ensureSubscriptionSchema();
if(($_GET['plans']??'')==='1'&&$_SERVER['REQUEST_METHOD']==='GET'){$rows=$pdo->query('SELECT id,name,monthly_price AS monthlyPrice,annual_price AS annualPrice,max_events AS maxEvents,max_tickets_per_event AS maxTicketsPerEvent,max_ticket_types AS maxTicketTypes,max_controllers AS maxControllers,commission,features FROM plans ORDER BY monthly_price')->fetchAll();foreach($rows as &$r){foreach(['monthlyPrice','annualPrice','maxEvents','maxTicketsPerEvent','maxTicketTypes','maxControllers'] as $k)$r[$k]=$r[$k]===null?null:(int)$r[$k];$r['commission']=(float)$r['commission'];$r['features']=json_decode($r['features']??'[]',true)?:[];}reply($rows);}
if(($_GET['admin']??'')==='1'){
  $admin=requireAdmin();
  if($_SERVER['REQUEST_METHOD']==='GET'){$rows=$pdo->query("SELECT s.id,u.id AS organizer_id,s.plan_id,p.name AS plan_name,COALESCE(s.status,'not_subscribed') AS status,COALESCE(s.billing_period,'monthly') AS billing_period,s.starts_at,s.ends_at,COALESCE(s.adjustment_type,'none') AS adjustment_type,COALESCE(s.adjustment_value,0) AS adjustment_value,s.adjustment_reason,p.monthly_price,p.annual_price,u.first_name,u.last_name,u.email FROM users u LEFT JOIN subscriptions s ON s.id=(SELECT MAX(s2.id) FROM subscriptions s2 WHERE s2.organizer_id=u.id) LEFT JOIN plans p ON p.id=s.plan_id WHERE u.role='organizer' ORDER BY u.first_name,u.last_name")->fetchAll();foreach($rows as &$row){$base=(int)($row['billing_period']==='annual'?$row['annual_price']:$row['monthly_price']);$value=(float)$row['adjustment_value'];$adjustment=$row['adjustment_type']==='percent'?$base*$value/100:($row['adjustment_type']==='fixed'?$value:0);$row['base_price']=$base;$row['adjustment_amount']=round($adjustment,2);$row['effective_price']=max(0,round($base+$adjustment,2));}$stats=$pdo->query("SELECT COUNT(*) AS total,COALESCE(SUM(status='active'),0) AS active,COALESCE(SUM(status='expired'),0) AS expired,COALESCE(SUM(status='pending_payment'),0) AS pending FROM subscriptions")->fetch();$stats['organizers']=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='organizer'")->fetchColumn();reply(['subscriptions'=>$rows,'stats'=>$stats]);}
  if($_SERVER['REQUEST_METHOD']!=='POST')reply(['error'=>'Méthode invalide.'],405);$d=body();$id=(int)($d['subscriptionId']??0);
  if(($d['action']??'')==='grant'&&$id===0){$organizerId=(int)($d['organizerId']??0);$q=$pdo->prepare("SELECT id,email FROM users WHERE id=? AND role='organizer'");$q->execute([$organizerId]);$target=$q->fetch();if(!$target)reply(['error'=>'Compte organisateur introuvable.'],404);$days=max(1,min(365,(int)($d['days']??30)));$start=date('Y-m-d H:i:s');$end=date('Y-m-d H:i:s',strtotime('+'.$days.' days'));$pdo->prepare("INSERT INTO subscriptions(organizer_id,plan_id,billing_period,status,starts_at,ends_at) VALUES(?,'free','monthly','active',?,?)")->execute([$organizerId,$start,$end]);$newId=(string)$pdo->lastInsertId();$pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$admin['email'],'subscription.granted','subscription',$newId,json_encode(['days'=>$days,'organizer'=>$target['email'],'new_account'=>true])]);reply(['updated'=>true,'status'=>'active','endsAt'=>$end,'subscriptionId'=>$newId]);}
  $q=$pdo->prepare("SELECT s.*,u.email,p.monthly_price,p.annual_price FROM subscriptions s JOIN users u ON u.id=s.organizer_id JOIN plans p ON p.id=s.plan_id WHERE s.id=?");$q->execute([$id]);$s=$q->fetch();if(!$s)reply(['error'=>'Abonnement introuvable.'],404);
  if(($d['action']??'')==='adjust_price'){$type=(string)($d['adjustmentType']??'');$value=(float)($d['adjustmentValue']??0);$reason=substr(trim((string)($d['reason']??'')),0,255);if(!in_array($type,['none','percent','fixed'],true)||!is_finite($value)||($type==='percent'&&($value< -100||$value>1000))||($type==='fixed'&&abs($value)>100000000))reply(['error'=>'Réduction ou majoration invalide.'],422);if($type==='none')$value=0;$base=(int)($s['billing_period']==='annual'?$s['annual_price']:$s['monthly_price']);$delta=$type==='percent'?$base*$value/100:($type==='fixed'?$value:0);$effective=max(0,round($base+$delta));$pdo->beginTransaction();try{$pdo->prepare('UPDATE subscriptions SET adjustment_type=?,adjustment_value=?,adjustment_reason=? WHERE id=?')->execute([$type,$value,$reason?:null,$id]);if($s['status']==='pending_payment')$pdo->prepare("UPDATE subscription_payments SET amount=? WHERE subscription_id=? AND status='pending'")->execute([$effective,$id]);$pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$admin['email'],'subscription.price_adjusted','subscription',(string)$id,json_encode(['type'=>$type,'value'=>$value,'base'=>$base,'effective'=>$effective,'reason'=>$reason,'organizer'=>$s['email']])]);$pdo->commit();reply(['updated'=>true,'basePrice'=>$base,'adjustment'=>$delta,'effectivePrice'=>$effective,'currency'=>'XAF']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();reply(['error'=>'La modification du tarif a échoué.'],500);}}
  if(($d['action']??'')==='grant'){$days=max(1,min(365,(int)($d['days']??30)));$start=date('Y-m-d H:i:s');$end=date('Y-m-d H:i:s',strtotime('+'.$days.' days'));$pdo->prepare("UPDATE subscriptions SET status='active',starts_at=?,ends_at=? WHERE id=?")->execute([$start,$end,$id]);$pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$admin['email'],'subscription.granted','subscription',(string)$id,json_encode(['days'=>$days,'organizer'=>$s['email']])]);reply(['updated'=>true,'status'=>'active','endsAt'=>$end]);}
  reply(['error'=>'Action inconnue.'],422);
}
$user=requireUser();
if(!in_array($user['role'],['organizer','admin'],true))reply(['error'=>'Réservé aux organisateurs.'],403);
if($_SERVER['REQUEST_METHOD']==='GET'){
  $q=$pdo->prepare("SELECT s.*,p.name AS plan_name,p.monthly_price,p.annual_price,p.max_events,p.max_tickets_per_event,p.max_ticket_types,p.max_controllers,p.commission,p.features FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE organizer_id=? ORDER BY CASE WHEN s.status IN ('active','grace') AND (s.ends_at IS NULL OR s.ends_at>=NOW()) THEN 0 ELSE 1 END,s.id DESC LIMIT 1");$q->execute([$user['id']]);$s=$q->fetch();
  if($s&&$s['ends_at']&&strtotime($s['ends_at'])<time()&&$s['status']==='active'){$pdo->prepare("UPDATE subscriptions SET status='expired' WHERE id=?")->execute([$s['id']]);$s['status']='expired';}
  $q=$pdo->prepare("SELECT COUNT(*) FROM events WHERE organizer_id=? AND status IN ('draft','published','ongoing')");$q->execute([$user['id']]);$events=(int)$q->fetchColumn();
  $q=$pdo->prepare('SELECT COUNT(DISTINCT es.user_id) FROM event_staff es JOIN events e ON e.id=es.event_id WHERE e.organizer_id=?');$q->execute([$user['id']]);$controllers=(int)$q->fetchColumn();
  if(!$s)reply(['subscription'=>null,'usage'=>['events'=>$events,'controllers'=>$controllers],'message'=>'Choisissez une formule pour activer votre espace organisateur.']);
  $s['features']=json_decode($s['features']??'[]',true)?:[];$s['usage']=['events'=>$events,'controllers'=>$controllers];
  $base=(int)($s['billing_period']==='annual'?$s['annual_price']:$s['monthly_price']);$delta=$s['adjustment_type']==='percent'?$base*(float)$s['adjustment_value']/100:($s['adjustment_type']==='fixed'?(float)$s['adjustment_value']:0);$s['base_price']=$base;$s['effective_price']=max(0,(int)round($base+$delta));
  $q=$pdo->prepare('SELECT id,amount,currency,status,created_at FROM subscription_payments WHERE subscription_id=? ORDER BY id DESC LIMIT 20');$q->execute([$s['id']]);$s['payments']=$q->fetchAll();
  reply(['subscription'=>$s,'usage'=>['events'=>$events,'controllers'=>$controllers]]);
}
if($_SERVER['REQUEST_METHOD']!=='POST')reply(['error'=>'Méthode invalide.'],405);
rateLimit('subscription:'.$user['id'],10,60);$d=body();$planId=(string)($d['planId']??'');$period=(string)($d['period']??'monthly');
if(!in_array($period,['monthly','annual'],true))reply(['error'=>'Durée invalide.'],422);
$q=$pdo->prepare('SELECT * FROM plans WHERE id=?');$q->execute([$planId]);$plan=$q->fetch();if(!$plan)reply(['error'=>'Formule introuvable.'],404);
$amount=(int)($period==='annual'?$plan['annual_price']:$plan['monthly_price']);
$pdo->beginTransaction();try{
  // Keep a paid, currently active plan while a new plan awaits provider confirmation.
  // Only replace it immediately for the zero-cost plan.
  if($amount===0)$pdo->prepare("UPDATE subscriptions SET status='cancelled' WHERE organizer_id=? AND status IN ('active','grace','pending_payment')")->execute([$user['id']]);
  $status=$amount===0?'active':'pending_payment';$start=$amount===0?date('Y-m-d H:i:s'):null;$end=$amount===0?date('Y-m-d H:i:s',strtotime($period==='annual'?'+1 year':'+1 month')):null;
  $pdo->prepare('INSERT INTO subscriptions(organizer_id,plan_id,billing_period,status,starts_at,ends_at) VALUES(?,?,?,?,?,?)')->execute([$user['id'],$planId,$period,$status,$start,$end]);$sid=(int)$pdo->lastInsertId();
  if($amount>0)$pdo->prepare("INSERT INTO subscription_payments(subscription_id,amount,status) VALUES(?,?,'pending')")->execute([$sid,$amount]);
  $pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$user['email'],'subscription.selected','subscription',(string)$sid,json_encode(['plan'=>$planId,'period'=>$period,'amount'=>$amount])]);
  $pdo->commit();reply(['subscriptionId'=>$sid,'status'=>$status,'amount'=>$amount,'currency'=>'XAF','message'=>$amount===0?'Formule gratuite activée.':'Paiement en attente. Aucun prestataire de paiement n’est configuré : votre abonnement ne sera pas activé avant une confirmation serveur vérifiée.']);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();reply(['error'=>'Impossible d’enregistrer la formule.'],500);}
